from z3 import Solver, Bool, Or, And, Not, sat
import itertools

n = 14
# Create boolean variables for each edge
edge_vars = {}
for u in range(n):
    for v in range(u+1, n):
        edge_vars[(u,v)] = Bool(f"e_{u}_{v}")

s = Solver()

# No independent set of size 3: for every triple, at least one edge present
for triple in itertools.combinations(range(n), 3):
    u, v, w = triple
    s.add(Or(edge_vars[(u,v)], edge_vars[(u,w)], edge_vars[(v,w)]))

# No clique of size 5: for every 5-set, not all 10 edges present
for five in itertools.combinations(range(n), 5):
    edges_in_five = [edge_vars[(u,v)] for u, v in itertools.combinations(five, 2)]
    s.add(Not(And(edges_in_five)))

print("Solving...")
result = s.check()
print("Result:", result)

if result == sat:
    model = s.model()
    edges = []
    for u in range(n):
        for v in range(u+1, n):
            if model[edge_vars[(u,v)]]:
                edges.append((u, v))
    print("Number of edges:", len(edges))
    print("Edges:", edges)
else:
    print("UNSAT")
